#include "mhc.hpp"
#include <hip/hip_runtime.h>
#include <windows.h>
#include <psapi.h>
#include <fstream>
#include <iostream>
#include <sstream>
#include <cstring>
using namespace strata_ext;
namespace {
void check(hipError_t e){if(e!=hipSuccess)throw std::runtime_error(hipGetErrorString(e));}
std::vector<std::vector<std::string>> table(const std::filesystem::path& path,size_t columns){std::ifstream f(path);if(!f)throw std::runtime_error("table open");std::vector<std::vector<std::string>> rows;std::string line;while(std::getline(f,line)){std::vector<std::string> cells;std::stringstream s(line);std::string value;while(std::getline(s,value,'\t'))cells.push_back(value);if(cells.size()!=columns)throw std::runtime_error("table columns");rows.push_back(cells);}return rows;}
std::string escape(const std::string& s){std::string out;for(char c:s){if(c=='\\'||c=='"')out+='\\';out+=c;}return out;}
std::vector<float> read(const std::filesystem::path& path,uint64_t count){artifact::FixtureView f{path,0,count*4};auto raw=f.read_exact(0,count*4);std::vector<float> x(count);std::memcpy(x.data(),raw.data(),raw.size());return x;}
void output(const std::filesystem::path& dir,const deepseek41::MhcTrace&t){std::filesystem::create_directory(dir);std::ofstream index(dir/"stages.tsv");for(const auto&[name,stage]:t.stages){std::ofstream f(dir/(name+".bin"),std::ios::binary);f.write((const char*)stage.values.data(),stage.values.size()*4);if(!f)throw std::runtime_error("stage write");index<<name<<'\t'<<stage.rows<<'\t'<<stage.columns<<'\t'<<stage.values.size()*4<<'\n';}std::ofstream atomic(dir/"atomic.tsv");for(const auto&r:t.requests)atomic<<r.source.span.name<<'\t'<<r.source.source.original_path.generic_string()<<'\t'<<r.source.span.absolute_offset<<'\t'<<r.batch<<'\t'<<r.packed<<'\t'<<r.input<<'\t'<<r.output<<'\n';}
}
int main(int argc,char**argv){try{
 if(argc==2&&std::string(argv[1])=="--identity"){std::cout<<"{\"source_id\":\""<<T12_SOURCE_ID<<"\"}";return 0;}
 if(argc!=9||std::string(argv[1])!="--run")throw std::runtime_error("--run PCI weights sources prefixes jobs controlled out");
 deepseek41::SourceSet sources;for(const auto&r:table(argv[4],5)){deepseek41::SourceFile f;f.shard_index=std::stoul(r[0]);f.original_size=std::stoull(r[1]);f.lfs_sha256=r[2];f.revision=r[3];f.original_path=r[4];if(sources.root.empty())sources.root=f.original_path.parent_path();sources.files.push_back(f);}
 std::vector<artifact::PrefixIndex> prefixes;std::string first;for(const auto&r:table(argv[5],2)){if(first.empty())first=r[1];prefixes.push_back(artifact::inspect_prefix(r[1],std::stoull(r[0])));}deepseek41::Artifact index(artifact::merge_prefixes(prefixes),deepseek41::inspect_metadata(first),sources);
 std::map<std::string,std::vector<std::string>> rows;for(const auto&r:table(argv[3],4))if(!rows.emplace(r[0],r).second)throw std::runtime_error("duplicate weight");
 auto weight=[&](const std::string&name){auto s=index.source_tensor("blk.0."+name+".weight");auto found=rows.find(s.span.name);if(found==rows.end())throw std::runtime_error("missing weight");const auto&r=found->second;if(std::stoull(r[1])!=s.span.absolute_offset||std::stoull(r[2])!=s.span.bytes||s.span.type_id!=0)throw std::runtime_error("weight source bind");artifact::FixtureView view{r[3],s.span.absolute_offset,s.span.bytes};return std::pair{s,view.read_exact(s.span.absolute_offset,s.span.bytes)};};
 auto weights=[&](const std::string&kind){deepseek41::MhcWeights w;auto fn=weight("hc_"+kind+"_fn");w.original_fn=fn.first;w.fn=std::move(fn.second);auto floats=[&](const std::string&n){auto raw=weight(n).second;std::vector<float> out(raw.size()/4);std::memcpy(out.data(),raw.data(),raw.size());return out;};w.base=floats("hc_"+kind+"_base");w.scale=floats("hc_"+kind+"_scale");w.norm=floats(kind+"_norm");return w;};auto attn=weights("attn"),ffn=weights("ffn");
 int count=0,selected=-1;check(hipGetDeviceCount(&count));for(int i=0;i<count;++i){char pci[64]={};check(hipDeviceGetPCIBusId(pci,sizeof(pci),i));if(std::string(pci)==argv[2])selected=i;}if(selected<0)throw std::runtime_error("exact PCI absent");check(hipSetDevice(selected));hipDeviceProp_t prop{};check(hipGetDeviceProperties(&prop,selected));
 size_t before_free=0,before_total=0,after_free=0,after_total=0;auto before=hipMemGetInfo(&before_free,&before_total);std::filesystem::path out(argv[8]);std::filesystem::create_directories(out);std::ostringstream summaries;summaries<<"[";bool firstjob=true;
 auto report=[&](const std::string&name,const deepseek41::MhcTrace&t){if(!firstjob)summaries<<",";firstjob=false;summaries<<"{\"name\":\""<<escape(name)<<"\",\"stages\":"<<t.stages.size()<<",\"primitive_peak\":"<<t.primitive_peak<<",\"scratch_peak\":"<<t.scratch_peak<<",\"cleanup_unknown\":"<<(t.cleanup_unknown?"true":"false")<<"}";};
 for(const auto&r:table(argv[6],5)){auto batch=std::stoul(r[1]);auto x=read(r[2],batch*20480);std::filesystem::path folder(r[3]);std::vector<std::vector<float>> inject;for(unsigned layer=0;layer<2;++layer)for(const auto&kind:{"attn","ffn"})inject.push_back(read(folder/("block"+std::to_string(layer)+"_"+kind+"_injected.bin"),batch*5120));measurement::Identity id;id.fixture_sha256=r[4];id.asset_sha256=sources.files[8].lfs_sha256;id.bundle_sha256=T12_SOURCE_ID;id.request_id=r[0];id.epoch=1;id.phase=measurement::Phase::Decode;auto trace=deepseek41::run_staggered(x,batch,attn,ffn,inject,id,argv[2]);output(out/r[0],trace);report(r[0],trace);}
 for(const auto&r:table(argv[7],2)){auto trace=deepseek41::run_controlled_mixes(read(r[1],24),1);output(out/("controlled-"+r[0]),trace);report("controlled-"+r[0],trace);}
 summaries<<"]";check(hipDeviceSynchronize());auto after=hipMemGetInfo(&after_free,&after_total);HMODULE modules[1024];DWORD needed=0;if(!EnumProcessModules(GetCurrentProcess(),modules,sizeof(modules),&needed)||needed>sizeof(modules))throw std::runtime_error("loaded modules");
 std::cout<<"{\"source_id\":\""<<T12_SOURCE_ID<<"\",\"pci\":\""<<argv[2]<<"\",\"arch\":\""<<prop.gcnArchName<<"\",\"jobs\":"<<summaries.str()<<",\"source_qualified\":false,\"loaded_modules\":[";
 for(unsigned i=0;i<needed/sizeof(HMODULE);++i){char p[32768];if(!GetModuleFileNameA(modules[i],p,sizeof(p)))throw std::runtime_error("module path");if(i)std::cout<<",";std::cout<<"\""<<escape(p)<<"\"";}std::cout<<"],\"before_status\":"<<int(before)<<",\"before_free\":";if(before==hipSuccess)std::cout<<before_free;else std::cout<<"null";std::cout<<",\"before_total\":";if(before==hipSuccess)std::cout<<before_total;else std::cout<<"null";std::cout<<",\"after_status\":"<<int(after)<<",\"after_free\":";if(after==hipSuccess)std::cout<<after_free;else std::cout<<"null";std::cout<<",\"after_total\":";if(after==hipSuccess)std::cout<<after_total;else std::cout<<"null";std::cout<<"}";return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 2;}}
